CREATE FUNCTION [higherlogic_thrive].[fnContactsUpdatedByContactKey_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [ContactKey],
            [UpdatedByContactKey],
            [ContactKey] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_thrive].[Contacts]
        WHERE
            [ContactKey] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[ContactKey],
            c.[UpdatedByContactKey],
            c.[ContactKey] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_thrive].[Contacts] c
        INNER JOIN
            CTE_RootParent p ON c.[ContactKey] = p.[UpdatedByContactKey]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [UpdatedByContactKey] IS NULL
    ORDER BY
        [RootParentID]
);
GO

